import{z as p,x as B,o as t,c as d,q as i,j as E,D as a,d as l,s as r,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"OpenVINO","description":"","frontmatter":{"title":"OpenVINO","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/openvino.md","filePath":"llm/openvino.md","lastUpdated":1791063341000}'),s={name:"llm/openvino.md"};function I(m,e,N,P,D,M){const o=B("Mermaid");return t(),d("div",null,[e[2]||(e[2]=i('<h1 id="openvino" tabindex="-1">OpenVINO <a class="header-anchor" href="#openvino" aria-label="Permalink to &quot;OpenVINO&quot;">​</a></h1><div class="epigraph"><p>把模型编译到 Intel CPU、核显与独显的统一运行时：设备叫 CPU/GPU/NPU，编译器做的是图优化与量化，而不是再训一份权重。</p><footer>—— Intel OpenVINO 文档与 NNCF 量化工具链</footer></div><p><a href="/llm/onnx-runtime">上一课</a>用 EP 把图画到多种后端。OpenVINO 是 Intel 硬件上的专用栈：IR（XML+bin 或从 ONNX/PyTorch 读入），<code>compile_model</code> 到指定 device，编译器在此完成图规范化、算子融合与 ISA 降级。LLM 路径有 Optimum-Intel、GenAI 库一类封装，处理 tokenizer 与逐步 generate。本课写它相对 ORT 的差：更贴 Intel ISA（AVX、<a href="/llm/amx-kernel">AMX</a>）、核显共享内存，以及 NPU 的形状限制。不把某一代酷睿的 token/s 写成常数。<span class="marginnote">IR（中间表示）可以理解为模型的「通用翻译稿」：不管你从 PyTorch 还是 ONNX 出发，先统一翻成 OpenVINO 自己的格式（XML 描述网络结构 + bin 存权重），编译器只针对这一种格式做优化，再落到具体芯片的机器指令上。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>目标设备是「没有独享 NVIDIA HBM 的机器」：服务器至强、笔记本核显、客户端 NPU。会计改写：带宽是 DDR 或 LPDDR，不是 HBM；算术是 AMX/AVX 或核显 EU。缺口是编译器必须把 Transformer 降到这些 ISA，并处理 KV 放哪——统一内存上 CPU 与 iGPU 共享，拷贝语义与 CUDA 不同：零拷贝省的是设备间搬运，省不掉 DDR 带宽本身这道关。动态 \\(n\\) 在 NPU 上往往要形状桶或 pad 到最大值，容量与碎片问题以另一种硬件回来。</p><p>量化几乎是默认：INT8/INT4 权重量化才能让 7B 进 16GB 笔记本。只压权重与全量化是两条不同的账：权重量化把激活留在 BF16，GEMM 吃不到 AMX 的 INT8 吞吐，但 decode 本来带宽受限，权重流减半就接近直接翻 token/s；权重与激活都落 INT8，GEMM 才能走上 AMX 矩阵扩展，收益集中在 prefill 的胖 GEMM。这与 GPU FP8 服务不是同一套核，质量要在目标设备上验收。<span class="marginnote">数字实例：7B 模型 BF16 权重约 14 GB，压到 INT8 约 7 GB、INT4 约 3.5 GB。16 GB 内存的笔记本还要留地方给操作系统、KV 缓存和应用，装不下 14 GB 的原始权重——这就是「量化几乎是默认」的算术。</span></p><p><span class="marginnote">OpenVINO 的「GPU」多指 Intel 核显/独显，不是 CUDA。文档里的 GPU 插件不要当成能跑 CUDA FA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>导出或用 Optimum 转 IR，指定 <code>device=CPU|GPU|NPU</code>。LLM 用官方 GenAI / pipeline 管 KV：逐步 generate 的调度、KV 生命周期与采样都在运行时里；应用层拿 numpy 自己拼会绕开 AMX 核与 KV 管理——运行时的核选择按设备与形状做过离线调优，绕开即退回通用路径，token/s 反而降。批处理在端侧常是 1，工作点永远在带宽区；优化是减 \\(W_{\\mathrm{bytes}}\\)（量化层数与分组粒度）与更好的 matmul 核，不是堆 \\(B\\)。与 ORT 选择：Intel 硬件优先 OpenVINO；要可移植到 NVIDIA 再 ORT/CUDA。</p>',9)),(t(),E(A,null,{default:a(()=>[r(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22PyTorch%20%2F%20ONNX%22%5D%20--%3E%20IR%5B%22OpenVINO%20IR%22%5D%0A%20%20IR%20--%3E%20CMP%5B%22compile_model%22%5D%0A%20%20CMP%20--%3E%20CPU%5B%22CPU%20AMX%2FAVX%22%5D%0A%20%20CMP%20--%3E%20IGPU%5B%22Intel%20GPU%22%5D%0A%20%20CMP%20--%3E%20NPU%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20NPU%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n("h2",{id:"机制",tabindex:"-1"},[l("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=n("p",null,[l("图捕获是第一道收益。IR 把算子图规范化后做常量折叠与融合：矩阵乘后的归一化与激活并入同一个核，attention 的多个小算子并成大核。为什么：每融合一层，中间张量就少一次 DDR 往返；端侧带宽贵，小算子各自读写内存时算得再快也在等内存。不做融合的图，GEMM 的提速会被访存账整段吃掉，这是「换了运行时却没快」最常见的原因。"),n("span",{class:"marginnote"},"可以把 DDR 内存到计算单元的每次搬运想象成食堂打饭排队：算子融合就是把几道菜合并到一个窗口一次打完，少排几次队。端侧内存通道窄（队列少），排队次数往往比打饭速度更先成为瓶颈。")],-1)),(t(),E(A,null,{default:a(()=>[r(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22INT8%20%E9%87%8F%E5%8C%96%22%5D%20--%3E%20W%5B%22%E8%B7%AF%E5%BE%84%E4%B8%80%EF%BC%9A%E5%8F%AA%E5%8E%8B%E6%9D%83%E9%87%8D%22%5D%0A%20%20Q%20--%3E%20WA%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%EF%BC%9A%E6%9D%83%E9%87%8D%2B%E6%BF%80%E6%B4%BB%E9%83%BD%20INT8%22%5D%0A%20%20W%20--%3E%20W1%5B%22decode%EF%BC%9A%E6%9D%83%E9%87%8D%E6%B5%81%E9%87%8F%E5%87%8F%E5%8D%8A%EF%BC%8Ctoken%2Fs%20%E6%8E%A5%E8%BF%91%E7%BF%BB%E5%80%8D%22%5D%0A%20%20W%20--%3E%20W2%5B%22GEMM%20%E4%BB%8D%E6%98%AF%20BF16%EF%BC%8C%E5%90%83%E4%B8%8D%E6%BB%A1%20AMX%22%5D%0A%20%20WA%20--%3E%20A1%5B%22prefill%20%E8%83%96%20GEMM%20%E8%B5%B0%20AMX%20%E7%9F%A9%E9%98%B5%E6%89%A9%E5%B1%95%22%5D%0A%20%20WA%20--%3E%20A2%5B%22%E6%95%B0%E5%80%BC%E8%AF%AF%E5%B7%AE%E6%9B%B4%E5%A4%A7%EF%BC%8C%E9%9C%80%E5%9C%A8%E7%9B%AE%E6%A0%87%E8%AE%BE%E5%A4%87%E9%AA%8C%E6%94%B6%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<p>AMX 把 decode 的瘦 GEMM 从 AVX 点积换成 tile 乘，每周期乘加数约为 BF16 tile 的两倍。它改变 token 吞吐的哪一段要拆开看：prefill 的胖 GEMM 计算受限，吃满 AMX 即近线性提速；decode 的瘦 GEMV 算术强度低、阵列喂不满，收益主要来自 INT8 权重把每步权重流量砍半。所以「INT8 加速几倍」必须拆 prefill 与 decode 分别报，混报会把带宽账记进算术账。强度仍受 DDR 限制，但常数更好。核显共享内存减少拷贝，但算力与带宽都低于独享 HBM GPU。NPU 对静态图友好，对投机、动态掩码不友好。工作点回到<a href="/llm/arithmetic-intensity-decode">屋顶线</a>，只是换了峰值数字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用数据中心 GPU 的 TPOT SLA 套笔记本：功耗墙与内存通道数不同，同一份 IR 在两边的瓶颈不在同一处。不要假设 NPU 支持任意自定义采样，投机解码的动态分支先查算子覆盖。下一课：Apple 的 <a href="/llm/mlx-apple">MLX</a>，统一内存故事更完整。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OpenVINO 把模型编译到 Intel CPU/iGPU/NPU；LLM 靠 GenAI 管 KV。</li><li>端侧 \\(B=1\\)，优化靠量化与 ISA 核，不靠堆并发。</li><li>设备名 GPU ≠ CUDA。</li><li>动态形状在 NPU 上要桶或 pad。</li><li>质量在目标量化路径上验收；INT8 收益拆 prefill（算术）与 decode（带宽）报。</li><li>出处：Intel OpenVINO 与 NNCF 文档；AMX 见 Intel SDM。</li></ul>',5))])}const U=p(s,[["render",I]]);export{C as __pageData,U as default};
